<script>
import { onMount } from 'svelte';
export let data;
const SUPABASE_URL='https://uawddygirnbpmkjhqcvu.supabase.co';
const KEY='sb_publishable_bEps0rM2t0HJsA6BPLjQPg_becZ1PsM';
const POS=['QB','RB','WR','TE','K','DEF'];
const ROSTER_LIMITS={QB:2,RB:2,WR:2,TE:1,FLEX:2,K:1,DEF:1,BENCH:5};
let mode='home',name='',room=null,teams=[],picks=[],activeRooms=[],loading=false,error='';
let pollTimer,timerTick,clientToken='',search='',positionFilter='ALL',cpuWorking=false,secondsLeft=60,lastPickSeen=null,shareNotice='';
let sideTab='players',chatMessages=[],chatText='',chatReady=true,chatError='',selectedTeamId='';
const players=Object.entries(data?.playerData?.players||{}).map(([id,p])=>({id,...p})).filter(p=>POS.includes(pos(p))&&(p.fn||p.first_name||p.ln||p.last_name));
function pos(p){const x=p.pos||p.position;return x==='DST'?'DEF':x||'UNK'}
function pname(p){const f=p.fn||p.first_name||'',l=p.ln||p.last_name||'';return pos(p)==='DEF'?(p.t||p.team||`${f} ${l}`.trim()):(`${f} ${l}`.trim()||p.full_name||'Unknown Player')}
function rank(p){const n=Number(p.search_rank??p.rank??9999);return Number.isFinite(n)&&n>0?n:9999}
function isAutoTeam(t){return !!t?.is_cpu&&!!t?.player_token} function isOpenCpu(t){return !!t?.is_cpu&&!t?.player_token}
function teamLabel(t){if(!t)return'Team';return isOpenCpu(t)?`GGL CPU · Slot ${t.draft_slot}`:(t.manager_name||`Team ${t.draft_slot}`)}
function hdr(prefer){return{apikey:KEY,Authorization:`Bearer ${KEY}`,'Content-Type':'application/json',...(prefer?{Prefer:prefer}:{})}}
async function req(path,o={}){const r=await fetch(`${SUPABASE_URL}/rest/v1/${path}`,{...o,headers:{...hdr(o.prefer),...(o.headers||{})}});if(!r.ok)throw new Error(await r.text()||`Request failed ${r.status}`);const t=await r.text();return t?JSON.parse(t):null}
function snakeSlot(n,c=10){const r=Math.floor((n-1)/c)+1,p=(n-1)%c+1;return r%2?p:c-p+1} function overallFor(r,s,c=10){const p=r%2?s:c-s+1;return(r-1)*c+p}
function ctx(n=Number(room?.current_pick||1)){const c=Number(room?.team_count||10),round=Math.floor((n-1)/c)+1,pickInRound=(n-1)%c+1,slot=snakeSlot(n,c);return{overallPick:n,round,pickInRound,slot,team:teams.find(t=>Number(t.draft_slot)===slot)}}
function buildRoster(teamPicks=[]){
 const roster={QB:[],RB:[],WR:[],TE:[],FLEX:[],K:[],DEF:[],BENCH:[]};
 for(const pk of teamPicks){
  const z=pk.position==='DST'?'DEF':pk.position;
  if(['QB','RB','WR','TE','K','DEF'].includes(z)&&roster[z].length<ROSTER_LIMITS[z]){roster[z].push(pk);continue}
  if(['RB','WR','TE'].includes(z)&&roster.FLEX.length<ROSTER_LIMITS.FLEX){roster.FLEX.push(pk);continue}
  roster.BENCH.push(pk);
 }
 return roster;
}
function teamRoster(id){return buildRoster(picks.filter(p=>p.team_id===id).sort((a,b)=>a.overall_pick-b.overall_pick))}
function projectedSlot(z,roster){
 if(['QB','RB','WR','TE','K','DEF'].includes(z)&&roster[z].length<ROSTER_LIMITS[z])return z;
 if(['RB','WR','TE'].includes(z)&&roster.FLEX.length<ROSTER_LIMITS.FLEX)return'FLEX';
 return'BENCH';
}
function viewTeam(t){if(!t)return;selectedTeamId=t.id;sideTab='team'}
function cycleTeam(dir){if(!teams.length)return;const idx=Math.max(0,teams.findIndex(t=>String(t.id)===String(viewedTeam?.id)));selectedTeamId=teams[(idx+dir+teams.length)%teams.length].id;sideTab='team'}
$: current=room?ctx():null;
$: myTeam=teams.find(t=>t.player_token===clientToken)||null;
$: viewedTeam=teams.find(t=>String(t.id)===String(selectedTeamId))||myTeam||teams[0]||null;
$: myTurn=room?.status==='drafting'&&current?.team?.player_token===clientToken&&!current?.team?.is_cpu;
$: drafted=new Set(picks.map(p=>String(p.player_id)));
$: myPicks=myTeam?picks.filter(p=>p.team_id===myTeam.id).sort((a,b)=>a.overall_pick-b.overall_pick):[];
$: viewedPicks=viewedTeam?picks.filter(p=>p.team_id===viewedTeam.id).sort((a,b)=>a.overall_pick-b.overall_pick):[];
$: viewedRoster=buildRoster(viewedPicks);
$: available=players.filter(p=>!drafted.has(String(p.id))).filter(p=>positionFilter==='ALL'||pos(p)===positionFilter).filter(p=>{const q=search.trim().toLowerCase();return!q||pname(p).toLowerCase().includes(q)||(p.t||p.team||'').toLowerCase().includes(q)}).sort((a,b)=>rank(a)-rank(b)).slice(0,120);
async function loadActive(){try{activeRooms=await req('mock_rooms?status=in.(lobby,drafting)&select=*&order=created_at.desc&limit=8')||[]}catch(e){console.error(e)}}
async function refreshChat(){if(!room?.id||sideTab!=='chat')return;try{chatMessages=await req(`mock_chat?room_id=eq.${room.id}&select=*&order=created_at.asc&limit=80`)||[];chatReady=true;chatError=''}catch(e){chatReady=false;chatError='Chat needs the Supabase mock_chat table setup.'}}
async function refresh(){if(!room?.id)return;try{const[rr,tt,pp]=await Promise.all([req(`mock_rooms?id=eq.${room.id}&select=*`),req(`mock_teams?room_id=eq.${room.id}&select=*&order=draft_slot.asc`),req(`mock_picks?room_id=eq.${room.id}&select=*&order=overall_pick.asc`)]);if(!rr?.length){leaveLocal();return}room=rr[0];teams=tt||[];picks=pp||[];if(!selectedTeamId&&teams.length)selectedTeamId=teams.find(t=>t.player_token===clientToken)?.id||teams[0].id;mode=['drafting','completed'].includes(room.status)?'draft':'room';if(sideTab==='chat')refreshChat();if(room.status==='drafting')requestAnimationFrame(maybeCpu)}catch(e){console.error(e)}}
function polling(){clearInterval(pollTimer);pollTimer=setInterval(refresh,1500)}
async function createRoom(){error='';loading=true;try{const made=await req('mock_rooms',{method:'POST',prefer:'return=representation',body:JSON.stringify({room_code:crypto.randomUUID().replace(/-/g,'').slice(0,12).toUpperCase(),host_id:clientToken,team_count:10,rounds:16,status:'lobby',current_pick:1})});room=made?.[0];if(!room)throw Error('Room could not be created.');await req('mock_teams',{method:'POST',prefer:'return=minimal',body:JSON.stringify(Array.from({length:10},(_,i)=>({room_id:room.id,draft_slot:i+1,is_cpu:true})))});await refresh();polling()}catch(e){error=e.message}finally{loading=false}}
async function join(r){room=r;await refresh();polling()}
async function claim(t){if(!name.trim()){error='Enter your name before claiming a team.';return}const mine=teams.find(x=>x.player_token===clientToken);if(mine&&mine.id!==t.id)await req(`mock_teams?id=eq.${mine.id}`,{method:'PATCH',prefer:'return=minimal',body:JSON.stringify({manager_name:null,player_token:null,is_cpu:true})});await req(`mock_teams?id=eq.${t.id}&is_cpu=eq.true&player_token=is.null`,{method:'PATCH',prefer:'return=minimal',body:JSON.stringify({manager_name:name.trim(),player_token:clientToken,is_cpu:false})});selectedTeamId=t.id;await refresh()}
async function release(t){await req(`mock_teams?id=eq.${t.id}`,{method:'PATCH',prefer:'return=minimal',body:JSON.stringify({manager_name:null,player_token:null,is_cpu:true})});await refresh()}
async function resumeManual(t){if(t?.player_token!==clientToken||!isAutoTeam(t))return;await req(`mock_teams?id=eq.${t.id}`,{method:'PATCH',prefer:'return=minimal',body:JSON.stringify({is_cpu:false})});await refresh()}
async function startDraft(){if(room?.host_id!==clientToken){error='Only the host can start the draft.';return}if(!teams.some(t=>t.player_token===clientToken)){error='Claim a slot before starting.';return}await req(`mock_rooms?id=eq.${room.id}`,{method:'PATCH',prefer:'return=minimal',body:JSON.stringify({status:'drafting',current_pick:1})});await refresh()}
function cpuScore(p,id,r){
 const roster=teamRoster(id),z=pos(p),slot=projectedSlot(z,roster);
 let x=10000-rank(p)*10;
 const starterOpen=slot!=='BENCH';
 if(starterOpen)x+=35;
 if(slot==='FLEX')x+=25;
 if((z==='RB'||z==='WR')&&starterOpen)x+=15;
 if(z==='QB'&&slot==='BENCH')x-=220;
 if(z==='QB'&&roster.QB.length>=3)x-=1200;
 if(z==='TE'&&slot==='BENCH'&&roster.TE.length>=2)x-=150;
 if((z==='K'||z==='DEF')&&slot==='BENCH')x-=2500;
 if(roster.BENCH.length>=ROSTER_LIMITS.BENCH&&slot==='BENCH')x-=10000;
 if(r>=8&&roster.QB.length<2&&z==='QB')x+=450;
 if(r>=10&&roster.RB.length<2&&z==='RB')x+=350;
 if(r>=10&&roster.WR.length<2&&z==='WR')x+=350;
 if(r>=10&&roster.TE.length<1&&z==='TE')x+=350;
 if(r>=12&&roster.FLEX.length<2&&['RB','WR','TE'].includes(z)&&slot==='FLEX')x+=250;
 if(r>=14&&roster.K.length<1&&z==='K')x+=1500;
 if(r>=14&&roster.DEF.length<1&&z==='DEF')x+=1500;
 return x;
}
function bestCpu(team,round){const pool=players.filter(p=>!drafted.has(String(p.id))).sort((a,b)=>cpuScore(b,team.id,round)-cpuScore(a,team.id,round));return pool[0]}
async function makePick(p,team=current?.team){if(!room||!team||room.status!=='drafting')return;const c=ctx(Number(room.current_pick));if(c.team?.id!==team.id)return;try{await req('mock_picks',{method:'POST',prefer:'return=minimal',body:JSON.stringify({room_id:room.id,team_id:team.id,overall_pick:c.overallPick,round:c.round,pick_in_round:c.pickInRound,player_id:String(p.id),player_name:pname(p),position:pos(p)})});const total=Number(room.team_count||10)*Number(room.rounds||16);await req(`mock_rooms?id=eq.${room.id}&current_pick=eq.${c.overallPick}`,{method:'PATCH',prefer:'return=minimal',body:JSON.stringify({current_pick:Math.min(c.overallPick+1,total+1),status:c.overallPick>=total?'completed':'drafting'})});await refresh()}catch(e){await refresh()}}
async function draftPlayer(p){if(myTurn)await makePick(p,current.team)} async function maybeCpu(){if(cpuWorking||room?.status!=='drafting')return;const c=ctx();if(!c.team?.is_cpu)return;cpuWorking=true;try{const p=bestCpu(c.team,c.round);if(p){await new Promise(r=>setTimeout(r,700));await makePick(p,c.team)}}finally{cpuWorking=false}}
async function autoHuman(){if(room?.status!=='drafting'||secondsLeft>0||cpuWorking)return;const c=ctx();if(!c.team||c.team.is_cpu)return;cpuWorking=true;try{await req(`mock_teams?id=eq.${c.team.id}&is_cpu=eq.false`,{method:'PATCH',prefer:'return=minimal',body:JSON.stringify({is_cpu:true})});const p=bestCpu(c.team,c.round);if(p)await makePick(p,c.team)}finally{cpuWorking=false}}
async function sendChat(){const text=chatText.trim();if(!text||!room?.id||!myTeam)return;chatText='';try{await req('mock_chat',{method:'POST',prefer:'return=minimal',body:JSON.stringify({room_id:room.id,player_token:clientToken,manager_name:myTeam.manager_name||name||'Manager',message:text})});await refreshChat()}catch(e){chatText=text;chatReady=false;chatError='Chat needs the Supabase mock_chat table setup.'}}
function changeSideTab(tab){sideTab=tab;if(tab==='team'&&!selectedTeamId&&myTeam)selectedTeamId=myTeam.id;if(tab==='chat')refreshChat()}
async function finishDraft(){if(room?.host_id!==clientToken)return;if(!confirm('Finish this mock now? The draft will become read-only.'))return;await req(`mock_rooms?id=eq.${room.id}`,{method:'PATCH',prefer:'return=minimal',body:JSON.stringify({status:'completed'})});await refresh()}
async function deleteDraft(){if(room?.host_id!==clientToken)return;if(!confirm('Delete this mock draft permanently?'))return;try{await req(`mock_chat?room_id=eq.${room.id}`,{method:'DELETE',prefer:'return=minimal'}).catch(()=>{});await req(`mock_picks?room_id=eq.${room.id}`,{method:'DELETE',prefer:'return=minimal'});await req(`mock_teams?room_id=eq.${room.id}`,{method:'DELETE',prefer:'return=minimal'});await req(`mock_rooms?id=eq.${room.id}`,{method:'DELETE',prefer:'return=minimal'});leaveLocal();await loadActive()}catch(e){error='Could not delete this mock. Check Supabase delete policies.'}}
function shareUrl(){if(!room?.id||typeof window==='undefined')return'';const u=new URL(window.location.href);u.search='';u.hash='';u.searchParams.set('mock',room.id);return u.toString()}
async function shareMock(){const url=shareUrl();if(!url)return;try{if(navigator.share){await navigator.share({title:'Join my GGL Mock Draft',text:'Join this GGL fantasy football mock draft.',url});shareNotice='Shared'}else if(navigator.clipboard){await navigator.clipboard.writeText(url);shareNotice='Link copied'}else{prompt('Copy this mock draft link:',url);shareNotice='Link ready'}}catch(e){if(e?.name!=='AbortError')error='Could not share the mock link.'}if(shareNotice)setTimeout(()=>shareNotice='',1800)}
function leaveLocal(){clearInterval(pollTimer);room=null;teams=[];picks=[];chatMessages=[];mode='home';error='';shareNotice='';sideTab='players';selectedTeamId='';if(typeof window!=='undefined')history.replaceState({},'',window.location.pathname)} async function leave(){leaveLocal();await loadActive()}
onMount(async()=>{clientToken=localStorage.getItem('ggl_mock_token')||crypto.randomUUID();localStorage.setItem('ggl_mock_token',clientToken);const mockId=new URLSearchParams(window.location.search).get('mock');if(mockId){try{const rows=await req(`mock_rooms?id=eq.${encodeURIComponent(mockId)}&select=*`);if(rows?.[0]){room=rows[0];await refresh();polling()}else{error='That mock draft is no longer available.';await loadActive()}}catch(e){error='Could not open that shared mock draft.';await loadActive()}}else await loadActive();timerTick=setInterval(()=>{if(room?.status!=='drafting'){secondsLeft=60;lastPickSeen=null;return}const n=Number(room.current_pick);if(lastPickSeen!==n){lastPickSeen=n;secondsLeft=60}else if(current?.team?.is_cpu){secondsLeft=60}else if(secondsLeft>0)secondsLeft--;if(secondsLeft<=0)autoHuman()},1000);return()=>{clearInterval(pollTimer);clearInterval(timerTick)}});
</script>
<svelte:head><title>GGL Mock Draft</title></svelte:head>
<div class="page"><header><small>GGL DRAFT LAB</small><h1>🎯 Mock Draft</h1><p>10-team · 2QB · 16 rounds · multiplayer</p></header>
{#if mode==='home'}<section class="card home"><label>Your name<input bind:value={name} placeholder="Ricardo"></label><button class="primary" onclick={createRoom}>Start New Mock</button><h3>Active Mocks</h3>{#each activeRooms as r}<button class="active" onclick={()=>join(r)}><b>{r.status==='drafting'?'Draft in progress':'Lobby open'}</b><span>Join →</span></button>{:else}<p class="muted">No active mocks.</p>{/each}</section>
{:else if mode==='room'}<div class="top"><b>Active Lobby</b><div><button onclick={shareMock}>↗ Share Mock</button><button onclick={leave}>Leave</button></div></div>{#if shareNotice}<div>{shareNotice}</div>{/if}<section class="card"><label>Your display name<input bind:value={name}></label></section><h2>Draft Order <small>{teams.filter(t=>!isOpenCpu(t)).length}/10 joined</small></h2><div class="teams">{#each teams as t}<div class:mine={t.player_token===clientToken} class="team"><b>{t.draft_slot}. {isOpenCpu(t)?'GGL CPU':t.manager_name}{isAutoTeam(t)?' · AUTO':''}</b>{#if t.player_token===clientToken}{#if isAutoTeam(t)}<button onclick={()=>resumeManual(t)}>Resume Manual</button>{:else}<button onclick={()=>release(t)}>Release</button>{/if}{:else if isOpenCpu(t)}<button onclick={()=>claim(t)}>Claim</button>{:else}<span>{isAutoTeam(t)?'Auto Draft':'Taken'}</span>{/if}</div>{/each}</div>{#if room.host_id===clientToken}<div class="host"><button class="primary" onclick={startDraft}>Start Draft</button><button onclick={shareMock}>↗ Share Mock</button><button class="danger" onclick={deleteDraft}>Delete Mock</button></div>{:else}<p class="muted">Waiting for the host to start.</p>{/if}
{:else if mode==='draft'}<div class="top"><button onclick={leave}>← Leave</button><div><small>{room.status==='completed'?'Draft complete':`Round ${current?.round} · Pick ${current?.overallPick} · Slot ${current?.slot}`}</small><b>{room.status==='completed'?'GGL Mock Complete':`${isOpenCpu(current?.team)?'GGL CPU':current?.team?.manager_name||'Team'}${isAutoTeam(current?.team)?' (AUTO)':''} is on the clock`}</b></div><div class:turn={myTurn} class="clock">{room.status==='completed'?'FINAL':current?.team?.is_cpu?'AUTO':`${secondsLeft}s`}</div></div><div class="hostbar"><button onclick={shareMock}>↗ Share Mock</button>{#if teams.find(t=>t.player_token===clientToken&&isAutoTeam(t))}<button onclick={()=>resumeManual(teams.find(t=>t.player_token===clientToken))}>Resume Manual</button>{/if}{#if room.host_id===clientToken}<button onclick={finishDraft} disabled={room.status==='completed'}>Finish Draft</button><button class="danger" onclick={deleteDraft}>Delete Mock</button>{/if}</div><div class="layout"><section class="panel"><h2>Draft Board <small>Snake · {picks.length}/{Number(room.team_count||10)*Number(room.rounds||16)}</small></h2><div class="scroll"><div class="board"><div class="head">Rd</div>{#each teams as t}<button class:viewingTeam={viewedTeam?.id===t.id} class="head teamHead" onclick={()=>viewTeam(t)}>S{t.draft_slot}<small>{isOpenCpu(t)?'CPU':t.manager_name}{isAutoTeam(t)?' · AUTO':''}</small></button>{/each}{#each Array.from({length:Number(room.rounds||16)},(_,i)=>i+1) as r}<div class="head">R{r}</div>{#each teams as t}{@const o=overallFor(r,Number(t.draft_slot),Number(room.team_count||10))}{@const pk=picks.find(x=>x.overall_pick===o)}<div class:now={room.current_pick===o&&room.status==='drafting'} class:mine={t.player_token===clientToken} class={`pick ${pk?`p-${pk.position}`:''}`}><small>#{o}</small><b>{pk?pk.player_name:(isOpenCpu(t)?'CPU':t.manager_name)}</b><span>{pk?.position||'—'}</span></div>{/each}{/each}</div></div></section><section class="panel sidepanel"><div class="sideTabs"><button class:on={sideTab==='players'} onclick={()=>changeSideTab('players')}>Players</button><button class:on={sideTab==='team'} onclick={()=>changeSideTab('team')}>Teams <small>{viewedPicks.length}/16</small></button><button class:on={sideTab==='chat'} onclick={()=>changeSideTab('chat')}>Chat</button></div>{#if sideTab==='players'}<div class="tabTitle"><b>Available Players</b><small>{myTurn?'Make your pick':'Best available'}</small></div><input bind:value={search} placeholder="Search player or team"><div class="filters">{#each ['ALL',...POS] as p}<button class:on={positionFilter===p} onclick={()=>positionFilter=p}>{p}</button>{/each}</div><div class="list">{#each available as p}<button class={`player p-${pos(p)}`} onclick={()=>draftPlayer(p)} disabled={!myTurn||room.status!=='drafting'}><span>{rank(p)<9999?rank(p):'—'}</span><b>{pname(p)}<small>{pos(p)} · {p.t||p.team||'FA'}</small></b><strong>{myTurn?'Draft':pos(p)}</strong></button>{/each}</div><p class="muted">Human picks have 60 seconds. A timeout switches that team to Auto Draft until Resume Manual is tapped.</p>{:else if sideTab==='team'}<div class="teamSwitcher"><button aria-label="Previous team" onclick={()=>cycleTeam(-1)}>‹</button><div><b>{teamLabel(viewedTeam)}</b><small>Slot {viewedTeam?.draft_slot}{viewedTeam?.id===myTeam?.id?' · Your team':''} · {viewedPicks.length}/16 drafted</small></div><button aria-label="Next team" onclick={()=>cycleTeam(1)}>›</button></div>{#if viewedTeam}<div class="roster"><div class="rosterGroup"><div class="rosterHead"><b>QB</b><span>{viewedRoster.QB.length}/2</span></div>{#each Array.from({length:2},(_,i)=>viewedRoster.QB[i]) as pk}<div class:emptySlot={!pk} class="rosterSlot p-QB"><strong>QB</strong>{#if pk}<b>{pk.player_name}<small>Pick #{pk.overall_pick}</small></b>{:else}<span>Open</span>{/if}</div>{/each}</div><div class="rosterGroup"><div class="rosterHead"><b>RB</b><span>{viewedRoster.RB.length}/2</span></div>{#each Array.from({length:2},(_,i)=>viewedRoster.RB[i]) as pk}<div class:emptySlot={!pk} class="rosterSlot p-RB"><strong>RB</strong>{#if pk}<b>{pk.player_name}<small>Pick #{pk.overall_pick}</small></b>{:else}<span>Open</span>{/if}</div>{/each}</div><div class="rosterGroup"><div class="rosterHead"><b>WR</b><span>{viewedRoster.WR.length}/2</span></div>{#each Array.from({length:2},(_,i)=>viewedRoster.WR[i]) as pk}<div class:emptySlot={!pk} class="rosterSlot p-WR"><strong>WR</strong>{#if pk}<b>{pk.player_name}<small>Pick #{pk.overall_pick}</small></b>{:else}<span>Open</span>{/if}</div>{/each}</div><div class="rosterGroup"><div class="rosterHead"><b>TE</b><span>{viewedRoster.TE.length}/1</span></div>{#each Array.from({length:1},(_,i)=>viewedRoster.TE[i]) as pk}<div class:emptySlot={!pk} class="rosterSlot p-TE"><strong>TE</strong>{#if pk}<b>{pk.player_name}<small>Pick #{pk.overall_pick}</small></b>{:else}<span>Open</span>{/if}</div>{/each}</div><div class="rosterGroup"><div class="rosterHead"><b>FLEX</b><span>{viewedRoster.FLEX.length}/2</span></div>{#each Array.from({length:2},(_,i)=>viewedRoster.FLEX[i]) as pk}<div class:emptySlot={!pk} class={`rosterSlot ${pk?`p-${pk.position}`:''}`}><strong>FLEX</strong>{#if pk}<b>{pk.player_name}<small>{pk.position} · Pick #{pk.overall_pick}</small></b>{:else}<span>RB / WR / TE</span>{/if}</div>{/each}</div><div class="rosterGroup compact"><div class="rosterHead"><b>K</b><span>{viewedRoster.K.length}/1</span></div>{#each Array.from({length:1},(_,i)=>viewedRoster.K[i]) as pk}<div class:emptySlot={!pk} class="rosterSlot p-K"><strong>K</strong>{#if pk}<b>{pk.player_name}<small>Pick #{pk.overall_pick}</small></b>{:else}<span>Open</span>{/if}</div>{/each}</div><div class="rosterGroup compact"><div class="rosterHead"><b>DEF</b><span>{viewedRoster.DEF.length}/1</span></div>{#each Array.from({length:1},(_,i)=>viewedRoster.DEF[i]) as pk}<div class:emptySlot={!pk} class="rosterSlot p-DEF"><strong>DEF</strong>{#if pk}<b>{pk.player_name}<small>Pick #{pk.overall_pick}</small></b>{:else}<span>Open</span>{/if}</div>{/each}</div><div class="rosterGroup benchGroup"><div class="rosterHead"><b>BENCH</b><span>{Math.min(viewedRoster.BENCH.length,5)}/5</span></div>{#each Array.from({length:5},(_,i)=>viewedRoster.BENCH[i]) as pk}<div class:emptySlot={!pk} class={`rosterSlot ${pk?`p-${pk.position}`:''}`}><strong>BN</strong>{#if pk}<b>{pk.player_name}<small>{pk.position} · Pick #{pk.overall_pick}</small></b>{:else}<span>Open bench slot</span>{/if}</div>{/each}</div></div>{:else}<p class="emptyState">No team selected.</p>{/if}{:else}<div class="tabTitle"><b>Draft Chat</b><small>{chatMessages.length} messages</small></div>{#if !chatReady}<p class="chatSetup">{chatError}</p>{/if}<div class="chatList">{#each chatMessages as m}<div class:mineChat={m.player_token===clientToken} class="chatMsg"><b>{m.manager_name}</b><span>{m.message}</span><small>{new Date(m.created_at).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})}</small></div>{:else}<p class="emptyState">No messages yet. Start the draft-room chat.</p>{/each}</div><div class="chatComposer"><input bind:value={chatText} onkeydown={(e)=>e.key==='Enter'&&sendChat()} placeholder="Message the draft room" disabled={!myTeam||!chatReady}><button onclick={sendChat} disabled={!chatText.trim()||!myTeam||!chatReady}>Send</button></div>{/if}</section></div>{/if}{#if error}<div class="error">{error}</div>{/if}</div>
